"use client";

import type { PointerEvent as ReactPointerEvent, RefObject } from "react";
import { useEffect, useEffectEvent, useRef, useState } from "react";

export type ColorAreaOffset = { x: number; y: number };
export type ColorAreaRect = { width: number; height: number };

export type ColorAreaPointer<Element extends HTMLElement> = {
  areaRef: RefObject<Element | null>;
  dragging: boolean;
  onPointerDown: (event: ReactPointerEvent) => void;
};

// window listeners rather than pointer capture, so pointerdown can emit immediately and gated effect owns cleanup
export function useColorArea<Element extends HTMLElement = HTMLDivElement>(
  onChange: (offset: ColorAreaOffset, rect: ColorAreaRect) => void,
  targetRef?: RefObject<Element | null>,
): ColorAreaPointer<Element> {
  const ownRef = useRef<Element | null>(null);
  const areaRef = targetRef ?? ownRef;
  const [dragging, setDragging] = useState(false);
  const emitDragChange = useEffectEvent(onChange);

  useEffect(() => {
    if (!dragging) return;

    function onMove(event: globalThis.PointerEvent) {
      const el = areaRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      emitDragChange({ x: event.clientX - rect.left, y: event.clientY - rect.top }, { width: rect.width, height: rect.height });
    }
    function onEnd() {
      setDragging(false);
    }

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onEnd);
    window.addEventListener("pointercancel", onEnd);

    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onEnd);
      window.removeEventListener("pointercancel", onEnd);
    };
  }, [dragging, areaRef]);

  function onPointerDown(event: ReactPointerEvent) {
    if (event.button !== 0) return;
    const el = areaRef.current;
    if (el) {
      const rect = el.getBoundingClientRect();
      onChange({ x: event.clientX - rect.left, y: event.clientY - rect.top }, { width: rect.width, height: rect.height });
    }
    setDragging(true);
    // Prevent native selection at the gesture source without restyling the entire document.
    event.preventDefault();
  }

  return { areaRef, dragging, onPointerDown };
}

// Generated from src/registry/sources/control-ui/recipes/color-picker.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const colorPickerKnobs = [
  "--cui-color-picker-output-swatch-radius",
  "--cui-color-picker-swatch-radius",
  "--cui-color-picker-area-radius",
  "--cui-color-picker-trigger-radius",
  "--cui-color-picker-trigger-shadow",
  "--cui-color-picker-slider-thumb-radius",
  "--cui-color-picker-slider-thumb-background",
] as const;
export type ColorPickerKnobStyle = Partial<Record<(typeof colorPickerKnobs)[number], string>>;

// HSVA (h 0-360, s/v 0-100, a 0-1) is source of truth: hue and saturation are indeterminate at black, white, and gray,
// so state stays HSVA across interaction and collapses to CSS string only for I/O.
export type Hsva = { h: number; s: number; v: number; a: number };
export type Rgba = { r: number; g: number; b: number; a: number };
export type Hsla = { h: number; s: number; l: number; a: number };
export type Oklcha = { L: number; C: number; H: number; a: number };
export type ColorFormat = "hex" | "rgb" | "hsl" | "oklch";

// tagged by color space so numeric fields stay exhaustive without casts
export type ChannelId = "r" | "g" | "b" | "h" | "s" | "l" | "okl" | "okc" | "okh" | "a";

export type ChannelSpec = {
  id: ChannelId;
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
};

const clamp = (n: number, min: number, max: number) => Math.min(max, Math.max(min, n));
const clamp01 = (n: number) => clamp(n, 0, 1);
const wrapHue = (h: number) => ((h % 360) + 360) % 360;
const round = (n: number) => Math.round(n);

// unrounded, so a conversion chain never snaps to the 8-bit grid before the final format
function hsvaToUnroundedRgba({ h, s, v, a }: Hsva): Rgba {
  const S = clamp01(s / 100);
  const V = clamp01(v / 100);
  const c = V * S;
  const hh = wrapHue(h) / 60;
  const x = c * (1 - Math.abs((hh % 2) - 1));
  const m = V - c;
  let r = 0;
  let g = 0;
  let b = 0;
  if (hh < 1) [r, g, b] = [c, x, 0];
  else if (hh < 2) [r, g, b] = [x, c, 0];
  else if (hh < 3) [r, g, b] = [0, c, x];
  else if (hh < 4) [r, g, b] = [0, x, c];
  else if (hh < 5) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];
  return { r: (r + m) * 255, g: (g + m) * 255, b: (b + m) * 255, a: clamp01(a) };
}

export function hsvaToRgba(hsva: Hsva): Rgba {
  const { r, g, b, a } = hsvaToUnroundedRgba(hsva);
  return { r: round(r), g: round(g), b: round(b), a };
}

export function rgbaToHsva({ r, g, b, a }: Rgba): Hsva {
  const R = clamp(r, 0, 255) / 255;
  const G = clamp(g, 0, 255) / 255;
  const B = clamp(b, 0, 255) / 255;
  const max = Math.max(R, G, B);
  const min = Math.min(R, G, B);
  const d = max - min;
  let h = 0;
  if (d !== 0) {
    if (max === R) h = 60 * (((G - B) / d) % 6);
    else if (max === G) h = 60 * ((B - R) / d + 2);
    else h = 60 * ((R - G) / d + 4);
  }
  const s = max === 0 ? 0 : d / max;
  return { h: wrapHue(h), s: s * 100, v: max * 100, a: clamp01(a) };
}

// hue carried verbatim so grays keep theirs
export function hsvaToHsla({ h, s, v, a }: Hsva): Hsla {
  const S = clamp01(s / 100);
  const V = clamp01(v / 100);
  const L = V * (1 - S / 2);
  const Sl = L === 0 || L === 1 ? 0 : (V - L) / Math.min(L, 1 - L);
  return { h: wrapHue(h), s: Sl * 100, l: L * 100, a: clamp01(a) };
}

export function hslaToHsva({ h, s, l, a }: Hsla): Hsva {
  const S = clamp01(s / 100);
  const L = clamp01(l / 100);
  const V = L + S * Math.min(L, 1 - L);
  const Sv = V === 0 ? 0 : 2 * (1 - L / V);
  return { h: wrapHue(h), s: Sv * 100, v: V * 100, a: clamp01(a) };
}

export function rgbaToHsla(rgba: Rgba): Hsla {
  return hsvaToHsla(rgbaToHsva(rgba));
}

export function hslaToRgba(hsla: Hsla): Rgba {
  return hsvaToRgba(hslaToHsva(hsla));
}

const srgbToLinear = (c: number) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const linearToSrgb = (c: number) => (c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055);

// rgb channels 0–255 → oklch (L 0–1, C ~0–0.4, H 0–360)
function rgbToOklch(r255: number, g255: number, b255: number): { L: number; C: number; H: number } {
  const r = srgbToLinear(clamp(r255, 0, 255) / 255);
  const g = srgbToLinear(clamp(g255, 0, 255) / 255);
  const b = srgbToLinear(clamp(b255, 0, 255) / 255);
  const l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
  const m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
  const s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
  const l_ = Math.cbrt(l);
  const m_ = Math.cbrt(m);
  const s_ = Math.cbrt(s);
  const L = 0.2104542553 * l_ + 0.793617785 * m_ - 0.0040720468 * s_;
  const A = 1.9779984951 * l_ - 2.428592205 * m_ + 0.4505937099 * s_;
  const B = 0.0259040371 * l_ + 0.7827717662 * m_ - 0.808675766 * s_;
  const C = Math.hypot(A, B);
  let H = (Math.atan2(B, A) * 180) / Math.PI;
  if (H < 0) H += 360;
  return { L, C, H };
}

function oklchToLinearRgb(L: number, C: number, H: number): [number, number, number] {
  const hr = (H * Math.PI) / 180;
  const a = C * Math.cos(hr);
  const b = C * Math.sin(hr);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  return [
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
  ];
}

const SRGB_GAMUT_TOLERANCE = 1e-4;
const CHROMA_BISECTION_STEPS = 20;
const fitsSrgb = (linear: number[]) => linear.every((channel) => channel >= -SRGB_GAMUT_TOLERANCE && channel <= 1 + SRGB_GAMUT_TOLERANCE);

// outside sRGB, chroma shrinks until the color fits: lightness and hue survive, where clipping channels shifts both
function oklchToRgb(L: number, C: number, H: number): { r: number; g: number; b: number } {
  const lightness = clamp01(L);
  let linear = oklchToLinearRgb(lightness, C, H);
  if (!fitsSrgb(linear)) {
    let fitting = 0;
    let overflowing = C;
    for (let step = 0; step < CHROMA_BISECTION_STEPS; step++) {
      const candidate = (fitting + overflowing) / 2;
      if (fitsSrgb(oklchToLinearRgb(lightness, candidate, H))) fitting = candidate;
      else overflowing = candidate;
    }
    linear = oklchToLinearRgb(lightness, fitting, H);
  }
  const [r, g, b] = linear;
  const encode = (channel: number) => clamp(linearToSrgb(channel) * 255, 0, 255);
  return { r: encode(r), g: encode(g), b: encode(b) };
}

export function hsvaToOklcha(hsva: Hsva): Oklcha {
  const { r, g, b } = hsvaToUnroundedRgba(hsva);
  const { L, C, H } = rgbToOklch(r, g, b);
  return { L, C, H, a: clamp01(hsva.a) };
}

export function oklchaToHsva({ L, C, H, a }: Oklcha): Hsva {
  const { r, g, b } = oklchToRgb(L, C, H);
  return rgbaToHsva({ r, g, b, a });
}

const hex2 = (n: number) => clamp(round(n), 0, 255).toString(16).padStart(2, "0");

// 3/4/6/8 digits, leading # optional; null on malformed input
export function hexToRgba(input: string): Rgba | null {
  const m = input.trim().replace(/^#/, "");
  const read = (h: string) => Number.parseInt(h, 16);
  if (m.length === 3 || m.length === 4) {
    if (!/^[0-9a-f]+$/i.test(m)) return null;
    const [red, green, blue, alpha] = m;
    if (!red || !green || !blue) return null;
    const r = read(red + red);
    const g = read(green + green);
    const b = read(blue + blue);
    const a = alpha ? read(alpha + alpha) / 255 : 1;
    return { r, g, b, a };
  }
  if (m.length === 6 || m.length === 8) {
    if (!/^[0-9a-f]+$/i.test(m)) return null;
    const r = read(m.slice(0, 2));
    const g = read(m.slice(2, 4));
    const b = read(m.slice(4, 6));
    const a = m.length === 8 ? read(m.slice(6, 8)) / 255 : 1;
    return { r, g, b, a };
  }
  return null;
}

export function rgbaToHex(rgba: Rgba, withAlpha = rgba.a < 1): string {
  const base = `#${hex2(rgba.r)}${hex2(rgba.g)}${hex2(rgba.b)}`;
  return withAlpha ? `${base}${hex2(clamp01(rgba.a) * 255)}` : base;
}

const trimNum = (n: number, d: number) => n.toFixed(d).replace(/\.?0+$/, "");

// near-neutral colors drop chroma+hue noise, matching shadcn v4 gray convention: `oklch(0.985 0 0)`
function oklchTriplet(L: number, C: number, H: number): string {
  const Ls = trimNum(L, 4);
  if (C < 1e-4) return `${Ls} 0 0`;
  return `${Ls} ${trimNum(C, 4)} ${trimNum(H, 3)}`;
}

export function formatColor(hsva: Hsva, format: ColorFormat, opts?: { alpha?: boolean }): string {
  const useAlpha = opts?.alpha !== false && hsva.a < 1;
  const alphaSuffix = useAlpha ? ` / ${trimNum(clamp01(hsva.a), 3)}` : "";
  switch (format) {
    case "hex": {
      return rgbaToHex(hsvaToRgba(hsva), useAlpha);
    }
    case "rgb": {
      const { r, g, b } = hsvaToRgba(hsva);
      return `rgb(${r} ${g} ${b}${alphaSuffix})`;
    }
    case "hsl": {
      const { h, s, l } = hsvaToHsla(hsva);
      return `hsl(${trimNum(wrapHue(h), 1)} ${trimNum(s, 1)}% ${trimNum(l, 1)}%${alphaSuffix})`;
    }
    case "oklch": {
      const { L, C, H } = hsvaToOklcha(hsva);
      return `oklch(${oklchTriplet(L, C, H)}${alphaSuffix})`;
    }
  }
}

const NAMED: Record<string, string> = {
  transparent: "#00000000",
  black: "#000000",
  white: "#ffffff",
  red: "#ff0000",
  green: "#008000",
  blue: "#0000ff",
  yellow: "#ffff00",
  orange: "#ffa500",
  purple: "#800080",
  gray: "#808080",
  grey: "#808080",
};

// CSS allows bare 0–1 number or percentage here
function readAlpha(token: string | undefined): number {
  if (token === undefined) return 1;
  const t = token.trim();
  if (t.endsWith("%")) return clamp01(Number.parseFloat(t) / 100);
  return clamp01(Number.parseFloat(t));
}

function parseHexColor(raw: string): Hsva | null {
  const rgba = hexToRgba(raw);
  return rgba ? rgbaToHsva(rgba) : null;
}

function parseRgbFunction(raw: string): Hsva | null {
  const match = raw.match(/^rgba?\(\s*([\d.]+%?)[\s,]+([\d.]+%?)[\s,]+([\d.]+%?)\s*(?:[/,]\s*([\d.]+%?))?\s*\)$/);
  if (!match) return null;
  const [, red, green, blue, alpha] = match;
  if (!red || !green || !blue) return null;
  const chan = (t: string) => (t.endsWith("%") ? (Number.parseFloat(t) / 100) * 255 : Number.parseFloat(t));
  return rgbaToHsva({ r: chan(red), g: chan(green), b: chan(blue), a: readAlpha(alpha) });
}

function parseHslFunction(raw: string): Hsva | null {
  const match = raw.match(/^hsla?\(\s*([\d.]+)(?:deg)?[\s,]+([\d.]+)%[\s,]+([\d.]+)%\s*(?:[/,]\s*([\d.]+%?))?\s*\)$/);
  if (!match) return null;
  const [, hue, saturation, lightness, alpha] = match;
  if (!hue || !saturation || !lightness) return null;
  return hslaToHsva({
    h: Number.parseFloat(hue),
    s: Number.parseFloat(saturation),
    l: Number.parseFloat(lightness),
    a: readAlpha(alpha),
  });
}

function parseOklchFunction(raw: string): Hsva | null {
  const match = raw.match(/^oklch\(\s*([\d.]+%?)\s+([\d.]+%?)\s+([\d.]+)\s*(?:[/,]\s*([\d.]+%?))?\s*\)$/);
  if (!match) return null;
  const [, lightness, chroma, hue, alpha] = match;
  if (!lightness || !chroma || !hue) return null;
  const L = lightness.endsWith("%") ? Number.parseFloat(lightness) / 100 : Number.parseFloat(lightness);
  // chroma as percentage is 0%→0, 100%→0.4 per CSS Color 4 reference range
  const C = chroma.endsWith("%") ? (Number.parseFloat(chroma) / 100) * 0.4 : Number.parseFloat(chroma);
  return oklchaToHsva({ L, C, H: Number.parseFloat(hue), a: readAlpha(alpha) });
}

// Pure parser: identical server/client results keep controlled color UI hydration-safe.
export function parseColor(input: string): Hsva | null {
  const raw = input.trim().toLowerCase();
  if (!raw) return null;

  const named = NAMED[raw];
  if (named) return parseHexColor(named);
  if (raw.startsWith("#")) return parseHexColor(raw);
  return parseRgbFunction(raw) ?? parseHslFunction(raw) ?? parseOklchFunction(raw);
}

// preserves hue (+sat at true black) on achromatic mutation so area/hue thumbs don't jump to red; `prev` = color before edit
export function preserveAchromatic(next: Hsva, prev: Hsva): Hsva {
  const out = { ...next };
  if (out.v === 0) {
    out.h = prev.h;
    out.s = prev.s;
  } else if (out.s === 0) {
    out.h = prev.h;
  }
  return out;
}

// channel set shown for given format. HEX borrows RGB channels (matching Figma).
export function getChannels(hsva: Hsva, format: ColorFormat): ChannelSpec[] {
  const alpha: ChannelSpec = { id: "a", label: "A", value: round(clamp01(hsva.a) * 100), min: 0, max: 100, step: 1 };
  switch (format) {
    case "hex":
    case "rgb": {
      const { r, g, b } = hsvaToRgba(hsva);
      return [
        { id: "r", label: "R", value: round(r), min: 0, max: 255, step: 1 },
        { id: "g", label: "G", value: round(g), min: 0, max: 255, step: 1 },
        { id: "b", label: "B", value: round(b), min: 0, max: 255, step: 1 },
        alpha,
      ];
    }
    case "hsl": {
      const { h, s, l } = hsvaToHsla(hsva);
      return [
        { id: "h", label: "H", value: round(wrapHue(h)), min: 0, max: 360, step: 1 },
        { id: "s", label: "S", value: round(s), min: 0, max: 100, step: 1 },
        { id: "l", label: "L", value: round(l), min: 0, max: 100, step: 1 },
        alpha,
      ];
    }
    case "oklch": {
      const { L, C, H } = hsvaToOklcha(hsva);
      return [
        { id: "okl", label: "L", value: Number(trimNum(L, 3)), min: 0, max: 1, step: 0.001 },
        { id: "okc", label: "C", value: Number(trimNum(C, 3)), min: 0, max: 0.4, step: 0.001 },
        { id: "okh", label: "H", value: round(wrapHue(H)), min: 0, max: 360, step: 1 },
        alpha,
      ];
    }
  }
}

// channel `id` already encodes its color space (r/g/b, h/s/l, okl/okc/okh, a), no format arg needed
export function setChannel(hsva: Hsva, id: ChannelId, value: number): Hsva {
  switch (id) {
    case "a":
      return { ...hsva, a: clamp01(value / 100) };
    case "r":
    case "g":
    case "b": {
      const rgba = hsvaToRgba(hsva);
      const next = { ...rgba, [id]: clamp(value, 0, 255) };
      return preserveAchromatic({ ...rgbaToHsva(next), a: hsva.a }, hsva);
    }
    case "h":
      return { ...hsva, ...hslaToHsva({ ...hsvaToHsla(hsva), h: wrapHue(value) }), a: hsva.a };
    case "s":
    case "l": {
      const hsla = hsvaToHsla(hsva);
      const key = id === "s" ? "s" : "l";
      const next = hslaToHsva({ ...hsla, [key]: clamp(value, 0, 100) });
      return preserveAchromatic({ ...next, h: hsla.h, a: hsva.a }, hsva);
    }
    case "okl":
    case "okc":
    case "okh": {
      const ok = hsvaToOklcha(hsva);
      let mapped = ok;
      if (id === "okl") mapped = { ...ok, L: clamp01(value) };
      else if (id === "okc") mapped = { ...ok, C: clamp(value, 0, 0.5) };
      else mapped = { ...ok, H: wrapHue(value) };
      return preserveAchromatic({ ...oklchaToHsva(mapped), a: hsva.a }, hsva);
    }
  }
}

// origin top-left: x → saturation (0 left…100 right), y → value (100 top…0 bottom), clamped
export function pointToSaturationValue(
  rect: { width: number; height: number },
  offsetX: number,
  offsetY: number,
): { s: number; v: number } {
  const s = rect.width <= 0 ? 0 : clamp01(offsetX / rect.width) * 100;
  const v = rect.height <= 0 ? 0 : (1 - clamp01(offsetY / rect.height)) * 100;
  return { s, v };
}

// angle → hue, radius → saturation (clamped to ring); origin top-left, wheel inscribed in box
export function pointToHueSat(rect: { width: number; height: number }, offsetX: number, offsetY: number): { h: number; s: number } {
  const cx = rect.width / 2;
  const cy = rect.height / 2;
  const dx = offsetX - cx;
  const dy = offsetY - cy;
  const radius = Math.min(cx, cy);
  const dist = Math.hypot(dx, dy);
  // atan2 with screen-y flipped so 0° points right and hue increases counter-clockwise → clockwise.
  let h = (Math.atan2(dy, dx) * 180) / Math.PI;
  h = wrapHue(h);
  const s = radius <= 0 ? 0 : clamp01(dist / radius) * 100;
  return { h, s };
}

// WCAG 2.x contrast for ColorPicker a11y advice; pure+SSR-safe
// "fix" nudges OKLCH lightness (hue+chroma held, so identity survives, move stays perceptually uniform) until it clears target ratio vs background
// adapted from theme-drawer's fixTextForeground; copied not imported (primitive installs by file-copy)

import { type Hsva, hsvaToOklcha, hsvaToRgba, oklchaToHsva, type Rgba } from "./color";

export type WcagLevel = "AA" | "AAA";
export type WcagLevels = { AA: boolean; AAA: boolean };

export const AA_RATIO = 4.5;
export const AAA_RATIO = 7;
export const TARGET_RATIO: Record<WcagLevel, number> = { AA: AA_RATIO, AAA: AAA_RATIO };

function channelLuminance(c: number): number {
  const s = c / 255;
  return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
}

// WCAG relative luminance — gamma-corrected sRGB.
export function luminanceFromRgb({ r, g, b }: { r: number; g: number; b: number }): number {
  return 0.2126 * channelLuminance(r) + 0.7152 * channelLuminance(g) + 0.0722 * channelLuminance(b);
}

export function contrastRatio(a: { r: number; g: number; b: number }, b: { r: number; g: number; b: number }): number {
  const la = luminanceFromRgb(a) + 0.05;
  const lb = luminanceFromRgb(b) + 0.05;
  return la > lb ? la / lb : lb / la;
}

export function wcagLevels(ratio: number): WcagLevels {
  return { AA: ratio >= AA_RATIO, AAA: ratio >= AAA_RATIO };
}

// next unmet level fix should aim for: AA first, then AAA, then nothing.
export function nextFixLevel(levels: WcagLevels): WcagLevel | null {
  if (!levels.AA) return "AA";
  if (!levels.AAA) return "AAA";
  return null;
}

// WCAG assumes an opaque backdrop, so a translucent foreground is measured as the color it actually paints over it
function paintedOver(color: Rgba, background: Rgba): Rgba {
  const blend = (channel: "r" | "g" | "b") => color[channel] * color.a + background[channel] * (1 - color.a);
  return { r: blend("r"), g: blend("g"), b: blend("b"), a: 1 };
}

export function contrastOf(color: Hsva, background: Rgba): number {
  return contrastRatio(paintedOver(hsvaToRgba(color), background), background);
}

// floored, never rounded, so a ratio just under a threshold can't read as passing it
export function formatContrastRatio(ratio: number): string {
  return (Math.floor(ratio * 100) / 100).toFixed(2);
}

// scans both directions, returns SMALLEST passing move; if none reach target, returns extreme with best worst-case ratio; null if already passing
export function fixColorForContrast(color: Hsva, background: Rgba, target: number = AA_RATIO): Hsva | null {
  const ok = hsvaToOklcha(color);
  const ratioAtL = (L: number) => contrastOf(oklchaToHsva({ L, C: ok.C, H: ok.H, a: color.a }), background);
  if (ratioAtL(ok.L) >= target) return null;

  let best: { L: number; dist: number } | null = null;
  for (let step = 0; step <= 100; step++) {
    const L = step / 100;
    if (ratioAtL(L) < target) continue;
    const dist = Math.abs(L - ok.L);
    if (!best || dist < best.dist) best = { L, dist };
  }
  const pick = (L: number) => oklchaToHsva({ L, C: ok.C, H: ok.H, a: color.a });
  if (best) return pick(best.L);
  // Nothing passed: fall back to whichever extreme maximizes ratio.
  return ratioAtL(0) >= ratioAtL(1) ? pick(0) : pick(1);
}

export type ContrastFailBand = { saturation: number; failsFrom: number; failsTo: number };

const BRIGHTNESS_BISECTION_STEPS = 12;

// `passes` holds at `passing` and flips once on the way to `failing`
function lastPassingBrightness(passes: (brightness: number) => boolean, passing: number, failing: number): number {
  if (!passes(passing)) return passing;
  let pass = passing;
  let fail = failing;
  for (let step = 0; step < BRIGHTNESS_BISECTION_STEPS; step++) {
    const middle = (pass + fail) / 2;
    if (passes(middle)) pass = middle;
    else fail = middle;
  }
  return pass;
}

// per saturation column of a saturation/brightness area, the brightness interval that misses `target` against `background`.
// luminance only rises with brightness, so the ratio bottoms out where the color matches the background and each edge is one bisection
export function contrastFailBands(color: Pick<Hsva, "h" | "a">, background: Rgba, target: number, columns = 32): ContrastFailBand[] {
  const backgroundLuminance = luminanceFromRgb(background);
  return Array.from({ length: columns + 1 }, (_, column) => {
    const saturation = (column / columns) * 100;
    const at = (brightness: number): Hsva => ({ h: color.h, s: saturation, v: brightness, a: color.a });
    const darkerThanBackground = (brightness: number) =>
      luminanceFromRgb(paintedOver(hsvaToRgba(at(brightness)), background)) <= backgroundLuminance;
    const meetsTarget = (brightness: number) => contrastOf(at(brightness), background) >= target;
    const matchingBackground = lastPassingBrightness(darkerThanBackground, 0, 100);
    return {
      saturation,
      failsFrom: lastPassingBrightness(meetsTarget, 0, matchingBackground),
      failsTo: lastPassingBrightness(meetsTarget, 100, matchingBackground),
    };
  });
}

import { formatColor, type Hsva, hsvaToOklcha, hsvaToRgba, oklchaToHsva, parseColor, rgbaToHsva } from "./color";

export type GradientType = "linear" | "radial" | "conic";

// the space the browser blends stops in: srgb passes through gray between distant hues, oklab and oklch stay vivid
export type GradientInterpolation = "srgb" | "oklab" | "oklch";

export type GradientStop = { id: string; position: number; color: string };

export type GradientValue = {
  type: GradientType;
  angle: number;
  interpolation: GradientInterpolation;
  stops: GradientStop[];
};

const clamp01 = (n: number) => Math.min(1, Math.max(0, n));
const lerp = (from: number, to: number, t: number) => from + (to - from) * t;
const byPosition = (a: { position: number }, b: { position: number }) => a.position - b.position;

// angle drives linear/conic direction, ignored for radial; srgb is the CSS default, so it stays implicit
export function formatGradient({ type, angle, interpolation, stops }: GradientValue): string {
  const space = interpolation === "srgb" ? "" : ` in ${interpolation}`;
  const list = [...stops]
    .sort(byPosition)
    .map((stop) => `${stop.color} ${Math.round(clamp01(stop.position) * 100)}%`)
    .join(", ");
  switch (type) {
    case "linear":
      return `linear-gradient(${Math.round(angle)}deg${space}, ${list})`;
    case "radial":
      return `radial-gradient(circle${space}, ${list})`;
    case "conic":
      return `conic-gradient(from ${Math.round(angle)}deg${space}, ${list})`;
  }
}

function mixSrgb(from: Hsva, to: Hsva, t: number): Hsva {
  const a = hsvaToRgba(from);
  const b = hsvaToRgba(to);
  return rgbaToHsva({ r: lerp(a.r, b.r, t), g: lerp(a.g, b.g, t), b: lerp(a.b, b.b, t), a: lerp(a.a, b.a, t) });
}

function mixOklab(from: Hsva, to: Hsva, t: number): Hsva {
  const a = hsvaToOklcha(from);
  const b = hsvaToOklcha(to);
  const radians = (hue: number) => (hue * Math.PI) / 180;
  const greenRed = lerp(a.C * Math.cos(radians(a.H)), b.C * Math.cos(radians(b.H)), t);
  const blueYellow = lerp(a.C * Math.sin(radians(a.H)), b.C * Math.sin(radians(b.H)), t);
  return oklchaToHsva({
    L: lerp(a.L, b.L, t),
    C: Math.hypot(greenRed, blueYellow),
    H: (Math.atan2(blueYellow, greenRed) * 180) / Math.PI,
    a: lerp(a.a, b.a, t),
  });
}

function mixOklch(from: Hsva, to: Hsva, t: number): Hsva {
  const a = hsvaToOklcha(from);
  const b = hsvaToOklcha(to);
  const shorterArc = ((b.H - a.H + 540) % 360) - 180;
  return oklchaToHsva({ L: lerp(a.L, b.L, t), C: lerp(a.C, b.C, t), H: a.H + shorterArc * t, a: lerp(a.a, b.a, t) });
}

const MIX: Record<GradientInterpolation, (from: Hsva, to: Hsva, t: number) => Hsva> = {
  srgb: mixSrgb,
  oklab: mixOklab,
  oklch: mixOklch,
};

// the color the gradient already paints at `position`, so a stop inserted there leaves the gradient unchanged
export function gradientColorAt({ stops, interpolation }: Pick<GradientValue, "stops" | "interpolation">, position: number): string {
  const sorted = [...stops].sort(byPosition);
  const before = sorted.findLast((stop) => stop.position <= position);
  const after = sorted.find((stop) => stop.position >= position);
  const nearest = before ?? after;
  if (!nearest) return "#ffffff";
  if (!before || !after) return nearest.color;
  const from = parseColor(before.color);
  const to = parseColor(after.color);
  if (!from || !to) return nearest.color;
  const span = after.position - before.position;
  const t = span === 0 ? 0 : (position - before.position) / span;
  return formatColor(MIX[interpolation](from, to, t), "hex");
}

