  return (
    <Button
      variant="surface"
      size="sm"
      iconOnly
      disabled={disabled}
      aria-label="Pick a color from the screen"
      data-control-ui="color-picker"
      data-slot="eye-dropper"
      className={className}
      onClick={pick}
      {...props}
